  input  logic clk        ,  // Clock
  input  logic srst       ,  // Active High Synchronous reset
  input  logic start      ,  // Start signal to begin search
  input  logic pause      ,  // Pause signal to temporarily halt search
  input  logic search_done,  // Indicates the datapath has completed the search
  output logic enable     ,  // Enables datapath to perform search
  output logic done          // High when search is completed
);

  // FSM states
  typedef enum logic [1:0] {
    IDLE,     // Waiting for start signal
    SEARCH,   // Actively searching
    DONE,     // Search completed
    PAUSED    // Search paused
  } fsm_state_t;

  fsm_state_t state, next_state;

  // State transition on clock or synchronous reset
  always_ff @(posedge clk or posedge srst) begin
    if (srst)
      state <= IDLE;        // Reset to IDLE
    else
      state <= next_state;  // Move to computed next state
  end

  // Next-state logic and output control
  always_comb begin
    // Default values
    next_state = state;
    enable     = 0;
    done       = 0;

    case (state)
      IDLE : begin
        if (start)
          next_state = SEARCH;  // Start search when start is asserted
      end

      SEARCH : begin
        enable = 1;             // Activate datapath
        if (pause)
          next_state = PAUSED;  // Pause requested
        else if (search_done)
          next_state = DONE;    // Done when datapath completes
      end

      PAUSED : begin
        if (!pause)
          next_state = SEARCH;  // Resume search when pause is deasserted
      end

      DONE : begin
        done = 1;               // Indicate completion
        next_state = IDLE;    // Go back to IDLE once start is deasserted
      end
    endcase
  end

endmodule
", "examples/heldout_linear_search/rtl/linear_search_datapath.sv": "module linear_search_datapath #(
  parameter DATA_WIDTH  = 8              ,
  parameter ADDR_WIDTH  = 4              ,
  parameter MEM_DEPTH   = 1 << ADDR_WIDTH,  // Total memory size
  parameter MAX_MATCHES = 8                 // Max number of indices to store in buffer
) (
  input  logic                                clk            ,  // Clock
  input  logic                                srst           ,  // Active High Synchronous reset
  input  logic                                enable         ,  // Enable signal from control FSM
  input  logic                                pause          ,  // Pause signal from control FSM
  input  logic [              DATA_WIDTH-1:0] key            ,  // Key to match against memory contents
  input  logic [              DATA_WIDTH-1:0] mem_read_data  ,  // Data read from memory
  output logic [              ADDR_WIDTH-1:0] mem_read_addr  ,  // Address to read from memory
  output logic [(MAX_MATCHES*ADDR_WIDTH)-1:0] match_indices  ,  // Buffer storing match indices
  output logic [   $clog2(MAX_MATCHES+1)-1:0] match_count    ,  // Number of matches found
  output logic                                search_done    ,  // High when search completes
  output logic                                match_overflow    // High if match buffer overflows
);

  logic [           ADDR_WIDTH-1:0] addr               ;
  logic [           ADDR_WIDTH-1:0] addr_dly           ;
  logic [$clog2(MAX_MATCHES+1)-1:0] match_count_temp   ;
  logic                             match_overflow_temp;
  logic                             enable_reg         ;
  logic                             mem_valid          ;
  logic                             pause_dly          ;

  always_ff @(posedge clk)
    enable_reg <= enable;

  always_ff @(posedge clk)
    pause_dly <= pause;

  always_ff @(posedge clk or posedge srst)
    if (srst) begin
      mem_valid <= 0;
    end else if (enable && !enable_reg) begin
      mem_valid <= 1;
    end else if (addr_dly == MEM_DEPTH - 1) begin
      mem_valid <= 0;
    end

  // Address generation logic
  always_ff @(posedge clk or posedge srst) begin
    if (srst) begin
      addr <= '0;  // Reset address
      addr_dly <= '0;
    end else if (pause_dly) begin
      // Hold address during pause
    end else if (enable && !enable_reg && addr == 0) begin
      addr <= 1;
      addr_dly <= addr;
    end else if (addr != 0) begin
      // Increment address or reset to 0 if search ends
      if (addr == MEM_DEPTH - 1) begin
        addr <= 0;
        addr_dly <= addr;
      end else begin
        addr <= addr + 1;
        addr_dly <= addr;
      end
    end else begin
      addr_dly <= addr;
    end
  end

  // Match logic and match buffer handling
  always_ff @(posedge clk or posedge srst) begin
    if (srst) begin
      match_count_temp    <= 0;
      match_overflow_temp <= 0;

      // Clear match_indices buffer
      for (int i = 0; i < MAX_MATCHES; i++) begin
        match_indices[i*ADDR_WIDTH+:ADDR_WIDTH] <= 0;
      end
    end else if (pause_dly) begin
      // Hold match logic during pause
    end else if (mem_valid && !search_done) begin
      if (mem_read_data == key) begin
        // If match found and room in buffer, store address
        if (match_count_temp < MAX_MATCHES) begin
          match_indices[match_count_temp*ADDR_WIDTH+:ADDR_WIDTH] <= addr_dly;
          match_count_temp                <= match_count_temp + 1;
        end else begin
          match_overflow_temp <= 1;  // Set overflow if buffer full
        end
      end
    end
    else if (search_done) begin
      match_count_temp    <= 0;
      match_overflow_temp <= 0;
    end
  end

  always_ff @(posedge clk or posedge srst)
    if (srst) begin
      match_count <= '0;
      match_overflow <= 0;
    end
    else if (search_done) begin
      match_count <= match_count_temp; 
      match_overflow <= match_overflow_temp;
    end

  // Search done signal generation
  always_ff @(posedge clk or posedge srst) begin
    if (srst) begin
      search_done <= 0;
    end else if (pause_dly) begin
      // Hold done state during pause
    end else if (enable && !search_done) begin
      // Set done when last address is reached
      if (addr_dly == MEM_DEPTH - 1) begin
        search_done <= 1;
      end
    end
    else begin
      search_done <= 0;
    end
  end

  // Connect internal address to memory read address output
  assign mem_read_addr = addr;

endmodule
", "examples/heldout_linear_search/rtl/linear_search_top.sv": "module linear_search_top #(
  parameter DATA_WIDTH  = 8              ,
  parameter ADDR_WIDTH  = 4              ,
  parameter MEM_DEPTH   = 1 << ADDR_WIDTH,  // Total memory entries
  parameter MAX_MATCHES = 8                 // Max matching indices to store
) (
  input  logic                                clk             ,
  input  logic                                srst            ,  // Active High Synchronous reset
  input  logic                                start           ,  // Start signal for search
  input  logic                                pause           ,  // Pause signal to temporarily halt search
  input  logic [              DATA_WIDTH-1:0] key             ,  // Key to search for

  // New memory write interface
  input  logic                                mem_write_en    ,  // Memory write enable
  input  logic [              ADDR_WIDTH-1:0] mem_write_addr  ,  // Address to write data to
  input  logic [              DATA_WIDTH-1:0] mem_write_data  ,  // Data to write into memory

  output logic                                done            ,  // Indicates search is complete
  output logic [   $clog2(MAX_MATCHES+1)-1:0] match_count     ,  // Number of matches found
  output logic [(MAX_MATCHES*ADDR_WIDTH)-1:0] match_indices   ,  // List of match indices
  output logic                                match_overflow     // High if more matches than MAX_MATCHES
);

  // Internal signals
  logic                  enable        ;  // Signal to enable the datapath
  logic                  search_done   ;  // Signal from datapath indicating search is complete
  logic [ADDR_WIDTH-1:0] mem_read_addr ;  // Address to be read from memory
  logic [DATA_WIDTH-1:0] mem_read_data ;  // Data read from memory

  // Dual-port style memory:
  // Allows search datapath to read while controller (external or user) writes
  logic [DATA_WIDTH-1:0] memory[0:MEM_DEPTH-1];

  // Memory write logic (only allowed when datapath is not enabled)
  always_ff @(posedge clk) begin
    if (mem_write_en && !enable) begin
      memory[mem_write_addr] <= mem_write_data;
    end
  end

  // Memory read logic for datapath (1-cycle latency)
  always_ff @(posedge clk) begin
    if (enable)
      mem_read_data <= memory[mem_read_addr];
  end

  // Datapath instantiation:
  // Performs linear search and stores match indices
  linear_search_datapath #(
    .DATA_WIDTH (DATA_WIDTH ),
    .ADDR_WIDTH (ADDR_WIDTH ),
    .MAX_MATCHES(MAX_MATCHES)
  ) datapath (
    .clk           (clk           ),
    .srst          (srst          ),
    .enable        (enable        ),
    .pause         (pause         ),
    .key           (key           ),
    .mem_read_data (mem_read_data ),
    .mem_read_addr (mem_read_addr ),
    .match_indices (match_indices ),
    .match_count   (match_count   ),
    .search_done   (search_done   ),
    .match_overflow(match_overflow)
  );

  // Controller instantiation:
  // Controls the enable signal and handles start/pause/done logic
  linear_search_ctrl ctrl (
    .clk        (clk        ),
    .srst       (srst       ),
    .start      (start      ),
    .pause      (pause      ),
    .search_done(search_done),
    .enable     (enable     ),
    .done       (done       )
  );

endmodule
"}, "specification": "# Linear Search Engine Specification Document

## **Introduction**
The **Linear Search Engine** is a parameterized, hierarchical RTL design that performs a **linear search** over a memory array to find all locations where a given key matches stored data. It supports **runtime memory writes**, **search control via a start/pause interface**, and outputs a **buffer of matched indices**, along with **match count** and **overflow detection**.

The design is organized into three main modules:
- `linear_search_top`: The top-level wrapper handling memory, interfaces, and submodule instantiation.
- `linear_search_ctrl`: An FSM-based controller that manages search initiation, pausing, and completion.
- `linear_search_datapath`: The logic responsible for iterating over memory and collecting match results.

---

## **Functional Overview**

### 1. **Search Operation**
- The module accepts a **key input** and performs a linear search over internal memory.
- If any memory entry matches the key, its **address index is recorded** into an internal buffer.
- Once the search completes, the output ports reflect the **total number of matches**, the **list of matched indices**, and whether an **overflow** occurred.

### 2. **Memory Interface**
- Internal memory supports **dual-port behavior**:
  - Port 1: Read-only, used by the datapath during search.
  - Port 2: Write-only, available externally when the search is **not enabled**.

### 3. **Control Logic**
- A **controller FSM** starts the search when `start` is asserted.
- The FSM supports **pausing/resuming** the search using the `pause` input.
- Once the search completes, a `done` signal is asserted.

---

## **Example Scenario**
### **Successful Search**

Memory Contents: [3, 5, 7, 5, 1] Key: 5

Result:

match_count = 2
match_indices = [1, 3]
done = 1
match_overflow = 0


### **Overflow Condition**

If more than MAX_MATCHES entries match the key:
Only first MAX_MATCHES indices are stored.
match_overflow = 1


---

## **Module Interface**

```verilog
module linear_search_top #(
  parameter DATA_WIDTH  = 8,
  parameter ADDR_WIDTH  = 4,
  parameter MEM_DEPTH   = 1 << ADDR_WIDTH,
  parameter MAX_MATCHES = 16
)(
  input  logic                         clk,
  input  logic                         srst,
  input  logic                         start,
  input  logic                         pause,
  input  logic [DATA_WIDTH-1:0]        key,

  input  logic                         mem_write_en,
  input  logic [ADDR_WIDTH-1:0]        mem_write_addr,
  input  logic [DATA_WIDTH-1:0]        mem_write_data,

  output logic                         done,
  output logic [$clog2(MAX_MATCHES+1)-1:0] match_count,
  output logic [(MAX_MATCHES*ADDR_WIDTH)-1:0] match_indices,
  output logic                         match_overflow
);
```
---

## **Module Parameters**

| **Parameter**     | **Type** | **Description**                                                                |
|-------------------|----------|--------------------------------------------------------------------------------|
| `DATA_WIDTH`      | Integer  | Width of each data element in memory.                                          |
| `ADDR_WIDTH`      | Integer  | Width of memory address.                                                       |
| `MEM_DEPTH`       | Integer  | Total number of memory entries. Derived from `ADDR_WIDTH`.                     |
| `MAX_MATCHES`     | Integer  | Maximum number of matched indices that can be stored in the result buffer.     |

---

## **Port Descriptions**

| **Signal**           | **Direction** | **Description**                                                                    |
|----------------------|---------------|------------------------------------------------------------------------------------|
| `clk`                | Input         | Clock signal. All logic operates on the rising edge.                               |
| `srst`               | Input         | Active-high synchronous reset. Resets internal states and outputs.                 |
| `start`              | Input         | Active-high for 1 clock cycle. Begins the search operation.                        |
| `pause`              | Input         | Active-high. Pauses the search when asserted; resumes on deassertion.              |
| `key`                | Input         | The value to be matched against each memory location.                              |
| `mem_write_en`       | Input         | Active-high. Enables memory write access. Only allowed when search is not running. |
| `mem_write_addr`     | Input         | Address to write into memory.                                                      |
| `mem_write_data`     | Input         | Data to be written into memory.                                                    |
| `done`               | Output        | Active-high. Asserted for one clock cycle after search completes.                  |
| `match_count`        | Output        | Number of memory addresses where the data matched the key.                         |
| `match_indices`      | Output        | Flat array of addresses where matches occurred. Width: `MAX_MATCHES * ADDR_WIDTH`. |
| `match_overflow`     | Output        | Active-high. Asserted if the number of matches exceeded `MAX_MATCHES`.             |

---

## **Design Hierarchy**

### `linear_search_top`
- Contains:
  - Local memory array (`memory`)
  - Write logic for external memory access
  - Instantiates:
    - `linear_search_ctrl`: FSM controller
    - `linear_search_datapath`: Match collection and address traversal logic

### `linear_search_ctrl`
- FSM States:
  | **State** | **Description**                          |
  |-----------|------------------------------------------|
  | `IDLE`    | Waiting for start                        |
  | `SEARCH`  | Actively iterating through memory        |
  | `PAUSED`  | Temporarily halts search on `pause`      |
  | `DONE`    | Signals completion, then returns to IDLE |

### `linear_search_datapath`
- Traverses memory addresses from `0` to `MEM_DEPTH - 1`
- Compares each data word with the `key`
- Stores matching addresses in `match_indices` if within buffer limit
- Flags overflow via `match_overflow` if matches exceed `MAX_MATCHES`
- Supports search **pause/resume** with internal state retention

